202	    /**
203	     * Applies the household rule to an owner about to be created. When the owner shares a
204	     * household (same last name and address, compared case-insensitively with collapsed
205	     * whitespace) with an existing owner, creation is rejected unless the request opted in via
206	     * {@code sharesHousehold}. When it opts in, the new owner and every existing household
207	     * member are stamped with the same stable {@code householdId}.
208	     *
209	     * <p>The new owner's household size after this create is recorded on it (the existing members
210	     * plus the owner itself), so an owner joining a household of three or more can be recognised.
211	     *
212	     * @throws DuplicateHouseholdException if a conflicting owner exists and the caller did not opt in
213	     */
214	    private void applyHouseholdPolicy(Owner owner, OwnerFieldsDto ownerFieldsDto, Collection<Owner> sameLastName) {
215	        List<Owner> members = householdDuplicateValidator.findHouseholdMembers(owner, sameLastName);
216	        owner.setHouseholdSize(members.size() + 1);
217	        if (members.isEmpty()) {
218	            return;
219	        }
220	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
221	            throw new DuplicateHouseholdException(owner.getLastName(), owner.getAddress());
222	        }
223	        String householdId = householdIdGenerator.generate(owner);
224	        owner.setHouseholdId(householdId);
225	        for (Owner member : members) {
226	            if (!householdId.equals(member.getHouseholdId())) {
227	                member.setHouseholdId(householdId);
228	                this.clinicService.saveOwner(member);
229	            }
230	        }
231	    }
